From 5b41b50eaa16e13a7ab88b155f5506cce67132ba Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:22:56 +0100
Subject: [PATCH] wallpapers/image: follow a wallpaper set from outside the
 config dialog

While the desktop settings showed an unapplied pick, setting a wallpaper
from Dolphin or plasma-apply-wallpaperimage was hidden by the preview
until the dialog closed. Now the dialog drops its preview and selects it.

BUG: 506131
---
 wallpapers/image/imagepackage/contents/ui/config.qml | 12 ++++++++++++
 1 file changed, 12 insertions(+)

diff --git a/wallpapers/image/imagepackage/contents/ui/config.qml b/wallpapers/image/imagepackage/contents/ui/config.qml
index 533cc1fff8..0780ac9808 100644
--- a/wallpapers/image/imagepackage/contents/ui/config.qml
+++ b/wallpapers/image/imagepackage/contents/ui/config.qml
@@ -138,6 +138,18 @@ ColumnLayout {
         value: root.wallpaperConfiguration.Image
     }

+    Connections {
+        // the wallpaper was set from outside (e.g. Dolphin): drop the preview and follow it
+        enabled: root.configDialog.currentWallpaper === "org.kde.image"
+        target: root.wallpaperConfiguration
+        function onValueChanged(key: string, value: var): void {
+            if (key === "Image") {
+                root.cfg_Image = value;
+                root.wallpaperConfiguration.PreviewImage = "null";
+            }
+        }
+    }
+
     spacing: 0

     Kirigami.FormLayout {
-- 
